const s = wb.getWorksheet('Sheet1');
for (const r of [1,5,9]) {
  const c = s.getRange(`D${r}`);
  c.setValue(`=IF(AND(B${r}="Description A",B${r+1}=""),"Single A",IF(AND(B${r}="Description B",B${r+1}=""),"Single B",IF(AND(B${r}="Description A",B${r+1}="Description B"),"Multiple","")))`);
  c.getStyle().setFill('#E2EFDA');
}
const out = [1,5,9].map(r => { const c = s.getRange(`D${r}`).getCell(); return [r, c.getValue?.(), c.getText?.(), s.getRange(`D${r}`).getFormulas?.()]; });
log(JSON.stringify(out));
